<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';
$action=$_GET['action']??'';
if($action==='register'&&$_SERVER['REQUEST_METHOD']==='POST'){$d=input();$name=trim($d['name']??'');$email=filter_var($d['email']??'',FILTER_VALIDATE_EMAIL);$password=(string)($d['password']??'');$profession=mb_substr(trim($d['profession']??''),0,120);$address=mb_substr(trim($d['address']??''),0,255);$interests=mb_substr(trim($d['interests']??''),0,500);$bio=mb_substr(trim($d['bio']??''),0,500);$website=mb_substr(trim($d['website']??''),0,255);if(strlen($name)<2||!$email||strlen($password)<8||strlen($profession)<2||strlen($interests)<2){http_response_code(422);exit(json_encode(['error'=>'Add your name, profession, interests, a valid email and a password of at least 8 characters.']));}if($website!==''&&!filter_var($website,FILTER_VALIDATE_URL)){http_response_code(422);exit(json_encode(['error'=>'Enter a complete website URL, including https://.']));}$q=$pdo->prepare('INSERT INTO users(name,email,password_hash,bio,website,profession,address,interests) VALUES(?,?,?,?,?,?,?,?)');try{$q->execute([$name,strtolower($email),password_hash($password,PASSWORD_DEFAULT),$bio,$website,$profession,$address,$interests]);}catch(PDOException $e){http_response_code(409);exit(json_encode(['error'=>'An account already exists for this email.']));}$userId=(int)$pdo->lastInsertId();exit(json_encode(issueSession($pdo,$userId,$name,$email)));}
if($action==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){$d=input();$q=$pdo->prepare('SELECT id,name,email,password_hash FROM users WHERE email=? LIMIT 1');$q->execute([strtolower(trim($d['email']??''))]);$u=$q->fetch();if(!$u||!password_verify((string)($d['password']??''),$u['password_hash'])){http_response_code(401);exit(json_encode(['error'=>'Email or password is incorrect.']));}exit(json_encode(issueSession($pdo,(int)$u['id'],$u['name'],$u['email'])));}
if($action==='me'&&$_SERVER['REQUEST_METHOD']==='GET'){exit(json_encode(['user'=>requireUser($pdo)]));}
if($action==='logout'&&$_SERVER['REQUEST_METHOD']==='POST'){$token=bearerToken();if($token){$q=$pdo->prepare('DELETE FROM user_sessions WHERE token_hash=?');$q->execute([hash('sha256',$token)]);}exit(json_encode(['ok'=>true]));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
function issueSession(PDO $pdo,int $userId,string $name,string $email):array{$token=bin2hex(random_bytes(32));$q=$pdo->prepare('INSERT INTO user_sessions(user_id,token_hash,expires_at) VALUES(?,?,NULL)');$q->execute([$userId,hash('sha256',$token)]);return['token'=>$token,'user'=>['id'=>$userId,'name'=>$name,'email'=>$email]];}
